#include <vector>

class Solution {
public:
    long long getDescentPeriods(std::vector<int>& prices) {
        long long ans = 1;
        long long currLen = 1;

        for (int i = 1; i < (int)prices.size(); ++i) {
            if (prices[i] == prices[i - 1] - 1) {
                currLen++;
            } else {
                currLen = 1;
            }
            ans += currLen;
        }
        return ans;
    }
};

class Solution {
    public long getDescentPeriods(int[] prices) {
        long ans = 1;
        long currLen = 1;

        for (int i = 1; i < prices.length; i++) {
            if (prices[i] == prices[i - 1] - 1) {
                currLen++;
            } else {
                currLen = 1;
            }
            ans += currLen;
        }
        return ans;
    }
}

