var getDescentPeriods = function(prices) {
    let ans = 1;
    let currLen = 1;

    for (let i = 1; i < prices.length; i++) {
        if (prices[i] === prices[i - 1] - 1) {
            currLen++;
        } else {
            currLen = 1;
        }
        ans += currLen;
    }
    return ans;
